'use client';

import { useState, useEffect } from 'react';
import { Plus, Trash2, Globe, AlertCircle, X, Loader2, Link2, Upload } from 'lucide-react';
import toast from 'react-hot-toast';

interface Sponsor {
  id: number;
  name: string;
  image_url: string;
  website_url: string;
}

export default function AdminSponsors() {
  const [sponsors, setSponsors] = useState<Sponsor[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [uploadMode, setUploadMode] = useState<'url' | 'file'>('url');
  const [error, setError] = useState('');
  const [formData, setFormData] = useState({ name: '', image_url: '', website_url: '' });
  const [loading, setLoading] = useState(true);

  const fetchSponsors = async () => {
    try {
      const res = await fetch('http://localhost:5001/api/sponsors', { credentials: 'include' });
      const data = await res.json();
      setSponsors(Array.isArray(data) ? data : []);
    } catch (err) { console.error(err); } finally { setLoading(false); }
  };

  useEffect(() => { fetchSponsors(); }, []);

  // Handle file conversion to Base64 (to store in image_url field)
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 1024 * 1024) { // 1MB limit
        setError('Image too large. Please use a file under 1MB.');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, image_url: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!formData.name.trim() || !formData.image_url.trim() || !formData.website_url.trim()) {
      setError('All fields are required.');
      return;
    }

    try {
      const res = await fetch('http://localhost:5001/api/sponsors', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (res.ok) {
        toast.success('Sponsor Added');
        setFormData({ name: '', image_url: '', website_url: '' });
        setIsModalOpen(false);
        fetchSponsors();
      }
    } catch (err) { setError('Connection failed.'); }
  };

  return (
    <div className="min-h-screen bg-[#020617] p-8 md:p-12 text-white">
      <div className="max-w-5xl mx-auto">
        <div className="flex justify-between items-center mb-10">
          <h1 className="text-3xl font-black uppercase italic">Partner <span className="text-red-600">Control</span></h1>
          <button onClick={() => setIsModalOpen(true)} className="bg-red-600 px-6 py-3 rounded-xl font-black uppercase text-[10px] tracking-widest flex items-center gap-2 hover:bg-red-700 transition-all shadow-lg shadow-red-600/20">
            <Plus size={14} /> Add New Partner
          </button>
        </div>

        {/* List of Sponsors */}
        <div className="space-y-3">
          {loading ? <Loader2 className="animate-spin mx-auto text-slate-700 mt-10" /> : sponsors.map((s) => (
            <div key={s.id} className="bg-slate-900/40 border border-slate-800 p-5 rounded-2xl flex items-center justify-between">
              <div className="flex items-center gap-6">
                <div className="w-20 h-14 bg-white rounded-lg flex items-center justify-center p-2">
                  <img src={s.image_url} alt="" className="max-w-full max-h-full object-contain" />
                </div>
                <p className="font-bold uppercase italic text-sm">{s.name}</p>
              </div>
              <button onClick={() => {
                 if(confirm('Delete?')) fetch(`http://localhost:5001/api/sponsors/${s.id}`, { method: 'DELETE', credentials: 'include' }).then(fetchSponsors);
              }} className="text-red-500 hover:bg-red-500/10 p-2 rounded-lg transition-colors">
                <Trash2 size={18} />
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* MODAL */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/90 backdrop-blur-sm" onClick={() => setIsModalOpen(false)} />
          <div className="relative bg-slate-900 w-full max-w-md rounded-[2.5rem] border border-slate-800 shadow-2xl overflow-hidden">
            <div className="p-8 border-b border-slate-800 flex justify-between items-center bg-slate-950/50">
              <h3 className="text-xl font-black uppercase italic tracking-tighter text-red-600">New Partner</h3>
              <X size={20} className="cursor-pointer" onClick={() => setIsModalOpen(false)} />
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-6">
              {error && <div className="text-red-500 text-[10px] font-black uppercase flex items-center gap-2"><AlertCircle size={14}/> {error}</div>}

              <input placeholder="COMPANY NAME" className="w-full bg-slate-950 border border-slate-800 p-4 rounded-xl text-sm font-bold uppercase italic focus:border-red-600 outline-none" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />

              {/* TOGGLE BUTTONS */}
              <div className="flex gap-2 p-1 bg-slate-950 rounded-xl border border-slate-800">
                <button type="button" onClick={() => setUploadMode('url')} className={`flex-1 py-2 text-[9px] font-black uppercase tracking-widest rounded-lg flex items-center justify-center gap-2 transition-all ${uploadMode === 'url' ? 'bg-red-600 text-white' : 'text-slate-500 hover:text-white'}`}>
                  <Link2 size={12}/> Image URL
                </button>
                <button type="button" onClick={() => setUploadMode('file')} className={`flex-1 py-2 text-[9px] font-black uppercase tracking-widest rounded-lg flex items-center justify-center gap-2 transition-all ${uploadMode === 'file' ? 'bg-red-600 text-white' : 'text-slate-500 hover:text-white'}`}>
                  <Upload size={12}/> File Upload
                </button>
              </div>

              {uploadMode === 'url' ? (
                <input placeholder="https://image-link.png" className="w-full bg-slate-950 border border-slate-800 p-4 rounded-xl text-sm outline-none focus:border-red-600" value={formData.image_url} onChange={e => setFormData({...formData, image_url: e.target.value})} />
              ) : (
                <div className="relative w-full bg-slate-950 border-2 border-dashed border-slate-800 rounded-xl p-6 text-center hover:border-red-600 transition-colors cursor-pointer">
                  <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
                  {formData.image_url && formData.image_url.startsWith('data:') ? (
                    <img src={formData.image_url} className="h-10 mx-auto rounded" />
                  ) : (
                    <div className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Click to select photo</div>
                  )}
                </div>
              )}

              <input placeholder="WEBSITE URL (e.g. https://adidas.com)" className="w-full bg-slate-950 border border-slate-800 p-4 rounded-xl text-sm outline-none focus:border-red-600" value={formData.website_url} onChange={e => setFormData({...formData, website_url: e.target.value})} />

              <button className="w-full bg-red-600 text-white font-black uppercase py-4 rounded-xl hover:bg-black transition-all text-[11px] tracking-widest shadow-xl shadow-red-600/20">
                Confirm Partner
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}